edits.newText:
// B-015 / B-031: show the jump glyph when the playing track's
// row is not currently visible in the browser viewport.
final hasTrack = playingPath != null && playingPath.isNotEmpty;
final needsJump = hasTrack && !browserController.isTrackVisible(playingPath!);
final showJumpGlyph = resolveJumpGlyphVisible(
  hasTrack: hasTrack,
  needsJump: needsJump,
);

